-- risque.
ALTER TABLE equipements MODIFY COLUMN statut_stock VARCHAR(30) NOT NULL DEFAULT 'affecte';
ALTER TABLE sites MODIFY COLUMN type VARCHAR(20) NOT NULL DEFAULT 'saisie';

